Your expense tracker is below. Add an amount, pick a category and see your total and a breakdown update. Entries may reset when you close the page, so note down your totals if you need them later.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f7f9;color:#1c1c1e}
h2{margin:0 0 12px;font-size:20px}
.card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select,button{font:inherit;padding:8px 10px;border-radius:8px;border:1px solid #c9ccd1;background:#fff}
input{flex:1;min-width:90px}
button{background:#2d6cdf;color:#fff;border:none;cursor:pointer}
button.x{background:none;color:#b3261e;padding:2px 8px}
.big{font-size:28px;font-weight:700}
.muted{color:#6b6f76;font-size:13px}
.bar{height:8px;border-radius:4px;background:#e4e7ec;margin:4px 0 10px}
.bar i{display:block;height:8px;border-radius:4px;background:#2d6cdf}
.item{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #eee}
.over{color:#b3261e}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
  </div>
  <div class="row" style="margin-top:8px">
    <input id="note" type="text" placeholder="Note (optional)">
    <button id="add">Add</button>
  </div>
</div>

<div class="card">
  <div class="muted">Total this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px;align-items:center">
    <span class="muted">Budget (₹)</span>
    <input id="budget" type="number" min="0" placeholder="e.g. 40000">
  </div>
  <div class="bar" style="margin-top:10px"><i id="bfill" style="width:0"></i></div>
  <div class="muted" id="bmsg"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:8px">By category</div>
  <div id="cats"></div>
</div>

<div class="card">
  <div class="muted">Entries</div>
  <div id="list"></div>
</div>

<script>
var items=[];
var $=function(i){return document.getElementById(i)};
function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
function esc(s){return s.replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function render(){
  var total=0,by={};
  items.forEach(function(e){total+=e.a;by[e.c]=(by[e.c]||0)+e.a});
  $("total").textContent=inr(total);
  var b=parseFloat($("budget").value)||0;
  if(b>0){
    var p=Math.min(100,total/b*100);
    $("bfill").style.width=p+"%";
    $("bmsg").innerHTML=total>b?'<span class="over">Over budget by '+inr(total-b)+'</span>':inr(b-total)+' left of '+inr(b);
  }else{$("bfill").style.width="0";$("bmsg").textContent="Set a budget to see how much is left."}
  var keys=Object.keys(by).sort(function(x,y){return by[y]-by[x]});
  $("cats").innerHTML=keys.length?keys.map(function(k){
    var pc=total?by[k]/total*100:0;
    return '<div class="row" style="justify-content:space-between"><span>'+k+'</span><span>'+inr(by[k])+' <span class="muted">('+Math.round(pc)+'%)</span></span></div><div class="bar"><i style="width:'+pc+'%"></i></div>';
  }).join(""):'<div class="muted">Nothing yet.</div>';
  $("list").innerHTML=items.length?items.map(function(e,i){
    return '<div class="item"><div>'+inr(e.a)+' · '+e.c+'<div class="muted">'+esc(e.n)+'</div></div><button class="x" data-i="'+i+'">Delete</button></div>';
  }).join(""):'<div class="muted">No entries yet.</div>';
}
$("add").onclick=function(){
  var a=parseFloat($("amt").value);
  if(!(a>0)){$("amt").focus();return}
  items.unshift({a:a,c:$("cat").value,n:$("note").value});
  $("amt").value="";$("note").value="";
  render();
};
$("list").onclick=function(ev){
  var i=ev.target.getAttribute("data-i");
  if(i!==null){items.splice(parseInt(i,10),1);render()}
};
$("budget").oninput=render;
render();
</script>
</body>
</html>
```
